  ('about','About Church Govern','Why Church Govern is being built and the principles guiding the platform.','[]'::jsonb,'published','2026-08-14T00:00:00Z','{"title":"About Church Govern","description":"Why Church Govern is being built and the principles guiding the platform.","canonicalUrl":"/about"}'::jsonb),
  ('product','Church Govern product suites','Explore the Church Govern office and member suites.','[]'::jsonb,'published','2026-08-14T00:00:00Z','{"title":"Church Govern product suites","description":"Explore the Church Govern office and member suites.","canonicalUrl":"/product"}'::jsonb),
  ('security-compliance','Security & compliance','The security, privacy and governance principles intended for Church Govern.','[]'::jsonb,'published','2026-08-14T00:00:00Z','{"title":"Security & compliance","description":"The security, privacy and governance principles intended for Church Govern.","canonicalUrl":"/security-compliance"}'::jsonb),
