insert into public.product_modules (suite_id,name,slug,eyebrow,short_description,overview,benefits,features,workflow,related_slugs,sort_order,status,published_at,seo)
select suite.id, seeded.name, seeded.slug, seeded.eyebrow, seeded.summary, seeded.overview, seeded.benefits, seeded.features, seeded.workflow, seeded.related_slugs, seeded.sort_order, 'published'::public.publish_status, '2026-08-14T00:00:00Z'::timestamptz, seeded.seo
from (values
  ('office-suite','Church Dashboard','church-dashboard','A clear view of church life','Bring the day’s priorities, activity and ministry signals into one calm workspace.','The Church Dashboard gives authorized teams a shared starting point for daily administration. The final widgets and measures will be configured with each church during implementation.','["See important activity at a glance","Reduce time spent moving between records","Help leaders act on timely information"]'::jsonb,'["Role-aware overview","Upcoming activity","Pending request indicators","Configurable quick actions"]'::jsonb,'["Sign in securely","Review the church overview","Open an item that needs attention","Complete the task in its source module"]'::jsonb,array['family-management','reports','communication']::text[],1,'{"title":"Church Dashboard","description":"Bring the day’s priorities, activity and ministry signals into one calm workspace.","canonicalUrl":"/product/church-dashboard"}'::jsonb),
  ('office-suite','Family Management','family-management','One connected family record','Organize household relationships, member details and pastoral context with care.','Family Management is designed to replace disconnected registers with searchable, permission-controlled family and member records.','["Keep family relationships connected","Find records without searching paper files","Support more informed pastoral care"]'::jsonb,'["Household profiles","Member relationships","Contact details","Record history"]'::jsonb,'["Create or locate a family","Add or update members","Record relevant details","Use the record across authorized workflows"]'::jsonb,array['record-management','communication','church-directory']::text[],2,'{"title":"Family Management","description":"Organize household relationships, member details and pastoral context with care.","canonicalUrl":"/product/family-management"}'::jsonb),
  ('office-suite','Church Administration','church-administration','Daily work, brought together','Coordinate routine office activity through consistent, trackable processes.','Church Administration provides a structured place for recurring administrative work. Exact processes remain configurable to the church’s governance model.','["Standardize recurring tasks","Give teams clearer ownership","Reduce duplicated administrative effort"]'::jsonb,'["Operational task views","Structured church records","Permission-based access","Activity history"]'::jsonb,'["Choose an administrative process","Enter or review the required information","Assign or complete the work","Retain a searchable history"]'::jsonb,array['record-management','request-certificate-processing','asset-management']::text[],3,'{"title":"Church Administration","description":"Coordinate routine office activity through consistent, trackable processes.","canonicalUrl":"/product/church-administration"}'::jsonb),
  ('office-suite','Record Management','record-management','Preserve every important record','Keep essential church information organized, searchable and protected.','Record Management centralizes records while helping authorized staff maintain consistent information. Retention rules and record types are defined during implementation.','["Reduce dependence on physical registers","Improve retrieval and continuity","Protect access to sensitive information"]'::jsonb,'["Structured record categories","Search and filtering","Access controls","Change history"]'::jsonb,'["Choose a record category","Create or digitize the record","Validate key details","Retrieve it through secure search"]'::jsonb,array['family-management','request-certificate-processing','reports']::text[],4,'{"title":"Record Management","description":"Keep essential church information organized, searchable and protected.","canonicalUrl":"/product/record-management"}'::jsonb),
  ('office-suite','Request & Certificate Processing','request-certificate-processing','From request to completion','Guide service and certificate requests through a visible, consistent workflow.','This module helps church offices receive, review and complete member requests without losing context across calls, paper notes and inboxes.','["Make request status easier to follow","Reduce repeated data entry","Create a consistent member experience"]'::jsonb,'["Request intake","Status tracking","Document preparation workflow","Completion history"]'::jsonb,'["Receive a member request","Verify the supporting record","Prepare and review the output","Mark complete and notify the requester"]'::jsonb,array['request-submission','record-management','notifications']::text[],5,'{"title":"Request & Certificate Processing","description":"Guide service and certificate requests through a visible, consistent workflow.","canonicalUrl":"/product/request-certificate-processing"}'::jsonb),
  ('office-suite','Finance Management','finance-management','Clearer stewardship workflows','Support accurate financial administration, donations and reporting.','Finance Management is intended to organize authorized church finance workflows. Financial controls, local accounting requirements and integrations require discovery before deployment.','["Improve visibility for authorized leaders","Create more consistent records","Reduce manual reporting effort"]'::jsonb,'["Income and expense records","Donation tracking","Permission controls","Financial summaries"]'::jsonb,'["Record an authorized transaction","Classify it consistently","Review supporting information","Use summaries for reporting"]'::jsonb,array['reports','subscription-history','church-dashboard']::text[],6,'{"title":"Finance Management","description":"Support accurate financial administration, donations and reporting.","canonicalUrl":"/product/finance-management"}'::jsonb),
  ('office-suite','Communication','communication','Reach the right people','Coordinate timely church communication from trusted member information.','Communication helps authorized teams prepare targeted updates using the church’s current records. Delivery channels and consent rules will depend on implementation.','["Keep updates consistent","Use relevant audience groups","Reduce disconnected contact lists"]'::jsonb,'["Audience groups","Message preparation","Announcement history","Consent-aware contact data"]'::jsonb,'["Choose an audience","Prepare the message","Review and send through an enabled channel","Retain a communication record"]'::jsonb,array['notifications','family-management','church-directory']::text[],7,'{"title":"Communication","description":"Coordinate timely church communication from trusted member information.","canonicalUrl":"/product/communication"}'::jsonb),
  ('office-suite','Asset Management','asset-management','Care for shared resources','Maintain a dependable register of church property and equipment.','Asset Management creates a structured inventory for church resources, ownership context and relevant maintenance information.','["Know what the church is responsible for","Keep asset details in one place","Support maintenance planning"]'::jsonb,'["Asset register","Categories and locations","Ownership details","Maintenance notes"]'::jsonb,'["Add an asset","Assign its category and location","Maintain relevant details","Review the register when planning"]'::jsonb,array['church-administration','reports','church-dashboard']::text[],8,'{"title":"Asset Management","description":"Maintain a dependable register of church property and equipment.","canonicalUrl":"/product/asset-management"}'::jsonb),
  ('office-suite','Cemetery Management','cemetery-management','Respectful, durable records','Organize cemetery information and preserve records for future generations.','Cemetery Management supports structured burial and plot records with controlled access. Field definitions and mapping needs must be confirmed with each church.','["Preserve historically important information","Make records easier to locate","Support consistent cemetery administration"]'::jsonb,'["Burial records","Plot references","Searchable details","Supporting notes"]'::jsonb,'["Locate or create a plot reference","Add the relevant record","Review details for accuracy","Retrieve it through authorized search"]'::jsonb,array['record-management','family-management','reports']::text[],9,'{"title":"Cemetery Management","description":"Organize cemetery information and preserve records for future generations.","canonicalUrl":"/product/cemetery-management"}'::jsonb),
  ('office-suite','Reports','reports','Turn records into understanding','Give authorized leaders useful summaries without rebuilding spreadsheets.','Reports brings together information captured across enabled modules. Available reports and export formats will be confirmed during implementation.','["Reduce repetitive reporting work","Support informed decisions","Use consistent source information"]'::jsonb,'["Module-based summaries","Filters","Authorized exports","Reusable report views"]'::jsonb,'["Choose a report","Apply the relevant filters","Review the result","Export only when authorized"]'::jsonb,array['church-dashboard','finance-management','record-management']::text[],10,'{"title":"Reports","description":"Give authorized leaders useful summaries without rebuilding spreadsheets.","canonicalUrl":"/product/reports"}'::jsonb),
  ('member-suite','Member Dashboard','member-dashboard','A simple personal starting point','Help members find updates, requests and profile information in one place.','The Member Dashboard is a secure self-service home for the member-facing capabilities enabled by a church.','["Find relevant services quickly","Stay connected to church activity","Reduce routine office enquiries"]'::jsonb,'["Personal overview","Church updates","Request status","Quick links"]'::jsonb,'["Sign in securely","Review the personal overview","Choose an available service","Follow the guided next step"]'::jsonb,array['notifications','request-submission','family-profile']::text[],11,'{"title":"Member Dashboard","description":"Help members find updates, requests and profile information in one place.","canonicalUrl":"/product/member-dashboard"}'::jsonb),
  ('member-suite','Family Profile','family-profile','Keep family information current','Give members a guided view of approved household details.','Family Profile allows members to view and, where enabled, request updates to information connected to their household.','["Improve record accuracy","Make relevant details easier to access","Create a clear update process"]'::jsonb,'["Household overview","Member details","Contact information","Update requests"]'::jsonb,'["Open the family profile","Review visible information","Submit an allowed update","Church staff reviews the change when required"]'::jsonb,array['profile-management','family-management','member-dashboard']::text[],12,'{"title":"Family Profile","description":"Give members a guided view of approved household details.","canonicalUrl":"/product/family-profile"}'::jsonb),
  ('member-suite','Request Submission','request-submission','Church services without uncertainty','Let members submit eligible requests and follow their progress online.','Request Submission creates a guided entry point for church services configured by the church office.','["Reduce avoidable office visits","Capture required details consistently","Give members clearer progress visibility"]'::jsonb,'["Service catalogue","Guided request forms","Supporting information","Status view"]'::jsonb,'["Choose an available service","Provide the requested information","Submit for church review","Follow the status to completion"]'::jsonb,array['request-certificate-processing','notifications','member-dashboard']::text[],13,'{"title":"Request Submission","description":"Let members submit eligible requests and follow their progress online.","canonicalUrl":"/product/request-submission"}'::jsonb),
  ('member-suite','Subscription History','subscription-history','A clear personal history','Help members review the subscription records made available by their church.','Subscription History presents member-visible subscription information in a consistent format. The exact definition of subscriptions requires product confirmation.','["Give members convenient reference","Reduce simple record enquiries","Keep a consistent personal view"]'::jsonb,'["History view","Period filters","Record details","Member-only access"]'::jsonb,'["Open subscription history","Choose a period","Review available records","Contact the church if correction is needed"]'::jsonb,array['finance-management','member-dashboard','notifications']::text[],14,'{"title":"Subscription History","description":"Help members review the subscription records made available by their church.","canonicalUrl":"/product/subscription-history"}'::jsonb),
  ('member-suite','Notifications','notifications','Timely updates, less noise','Keep members informed about requests, events and church communication.','Notifications brings member-relevant updates into one view. Supported delivery channels and preferences will depend on deployment.','["Make important updates easier to notice","Keep request communication connected","Support timely engagement"]'::jsonb,'["In-app updates","Read status","Request notifications","Preference-ready architecture"]'::jsonb,'["Receive a relevant update","Open it for context","Take action when requested","Retain it for later reference"]'::jsonb,array['communication','request-submission','member-dashboard']::text[],15,'{"title":"Notifications","description":"Keep members informed about requests, events and church communication.","canonicalUrl":"/product/notifications"}'::jsonb),
  ('member-suite','Church Directory','church-directory','Find approved connections','Offer a privacy-aware directory based on church permissions and member choices.','Church Directory can help members find approved people or groups while respecting visibility rules. Consent and field visibility must be configured before launch.','["Support community connection","Keep directory information current","Respect member visibility choices"]'::jsonb,'["Permission-aware listings","Search","Member-approved details","Configurable visibility"]'::jsonb,'["Open the directory","Search an approved listing","View permitted information","Use the church’s enabled contact path"]'::jsonb,array['family-management','profile-management','communication']::text[],16,'{"title":"Church Directory","description":"Offer a privacy-aware directory based on church permissions and member choices.","canonicalUrl":"/product/church-directory"}'::jsonb),
  ('member-suite','Profile Management','profile-management','Personal details, responsibly managed','Help members maintain permitted profile and preference information.','Profile Management gives members control over the information and preferences their church has chosen to make self-service.','["Improve information accuracy","Make privacy choices clearer","Reduce routine change requests"]'::jsonb,'["Personal details","Contact preferences","Visibility controls","Secure account settings"]'::jsonb,'["Open profile settings","Review editable details","Save or request a change","Confirm the updated information"]'::jsonb,array['family-profile','church-directory','notifications']::text[],17,'{"title":"Profile Management","description":"Help members maintain permitted profile and preference information.","canonicalUrl":"/product/profile-management"}'::jsonb)
) as seeded(suite_slug,name,slug,eyebrow,summary,overview,benefits,features,workflow,related_slugs,sort_order,seo)
join public.product_suites suite on suite.slug=seeded.suite_slug
on conflict (slug) do nothing;

