insert into public.blog_posts(category_id,slug,title,excerpt,content,author_name,read_time_minutes,keywords,status,featured,published_at,seo)
select category.id,seeded.slug,seeded.title,seeded.excerpt,seeded.content,seeded.author_name,seeded.read_time_minutes,'{}'::text[],'published'::public.publish_status,seeded.featured,seeded.published_at,seeded.seo from (values
  ('digital-transformation','building-a-responsible-digitization-plan','Building a responsible digitization plan for church records','A practical starting point for deciding what to digitize, how to prioritize, and where safeguards belong.','[{"heading":"Begin with purpose","paragraphs":["Digitization is most useful when it answers a clear operational or pastoral need. Start by identifying the records people struggle to locate, the processes that create repeated work, and the information that is most vulnerable to loss."]},{"heading":"Prioritize with care","paragraphs":["A simple inventory can group records by condition, frequency of use, sensitivity and long-term value. This helps a church plan manageable phases instead of attempting a risky one-time migration."]},{"heading":"Protect context as well as documents","paragraphs":["Scanning a page is only one part of preservation. Consistent names, dates, categories, permissions and review steps make the resulting information dependable and easier to find."]}]'::jsonb,'Church Govern editorial team',6,true,'2026-07-28T00:00:00Z'::timestamptz,'{"title":"Building a responsible digitization plan for church records","description":"A practical starting point for deciding what to digitize, how to prioritize, and where safeguards belong.","canonicalUrl":"/blogs/building-a-responsible-digitization-plan"}'::jsonb),
  ('church-administration','less-administration-more-ministry','Less administration, more time for ministry','Where connected workflows can reduce repetitive work for clergy and church office teams.','[{"heading":"Look for repeated handoffs","paragraphs":["Administrative friction often hides in small handoffs: a request copied from a message into a register, a member asked for details the church already holds, or a report rebuilt from several files."]},{"heading":"Create one dependable path","paragraphs":["A connected workflow gives each request a clear entry point, owner and status. The goal is not to remove human care, but to protect more time for it."]},{"heading":"Measure what improves","paragraphs":["Track fewer missing details, shorter response time and reduced duplicate entry. These practical signals are often more useful than counting how many features have been enabled."]}]'::jsonb,'Church Govern editorial team',5,true,'2026-07-12T00:00:00Z'::timestamptz,'{"title":"Less administration, more time for ministry","description":"Where connected workflows can reduce repetitive work for clergy and church office teams.","canonicalUrl":"/blogs/less-administration-more-ministry"}'::jsonb),
  ('governance','privacy-by-design-for-church-data','Privacy by design for sensitive church information','Seven questions to ask before introducing a new digital process or member service.','[{"heading":"Collect with a reason","paragraphs":["Teams should be able to explain why each field is needed, who can see it, how long it is kept and how a person can ask for a correction."]},{"heading":"Make access deliberate","paragraphs":["Role-based access works best when permissions reflect real responsibilities and are reviewed when responsibilities change."]},{"heading":"Plan for the full lifecycle","paragraphs":["Privacy considerations continue after collection. Storage, exports, backups, corrections, deletion requests and incident response all need accountable processes."]}]'::jsonb,'Church Govern editorial team',7,true,'2026-06-24T00:00:00Z'::timestamptz,'{"title":"Privacy by design for sensitive church information","description":"Seven questions to ask before introducing a new digital process or member service.","canonicalUrl":"/blogs/privacy-by-design-for-church-data"}'::jsonb),
  ('record-management','a-healthier-member-record','What makes a healthier member record?','A simple framework for accurate, useful and respectfully maintained member information.','[{"heading":"Useful, not excessive","paragraphs":["A healthy record contains information that supports a defined church purpose. More fields do not automatically create better understanding."]},{"heading":"Current and accountable","paragraphs":["Give members and authorized staff clear ways to identify outdated information and request corrections, with review where the information is sensitive."]},{"heading":"Connected to action","paragraphs":["Well-maintained records reduce repeated questions, improve communication and support pastoral follow-up without replacing personal judgment."]}]'::jsonb,'Church Govern editorial team',4,false,'2026-06-02T00:00:00Z'::timestamptz,'{"title":"What makes a healthier member record?","description":"A simple framework for accurate, useful and respectfully maintained member information.","canonicalUrl":"/blogs/a-healthier-member-record"}'::jsonb),
  ('church-finance','clearer-church-finance-workflows','Designing clearer church finance workflows','How consistency, permissions and review points can strengthen everyday stewardship.','[{"heading":"Define the path","paragraphs":["Clear finance workflows specify who records, who reviews and what supporting information is required for each type of transaction."]},{"heading":"Separate responsibilities","paragraphs":["Permission design should reflect the church’s governance and review model. No software feature replaces appropriate oversight."]},{"heading":"Report from consistent records","paragraphs":["When records use shared categories and review steps, periodic summaries become easier to prepare and explain."]}]'::jsonb,'Church Govern editorial team',6,true,'2026-05-19T00:00:00Z'::timestamptz,'{"title":"Designing clearer church finance workflows","description":"How consistency, permissions and review points can strengthen everyday stewardship.","canonicalUrl":"/blogs/clearer-church-finance-workflows"}'::jsonb),
  ('church-technology','choosing-technology-that-serves-community','Choosing technology that serves community','A church-focused checklist for evaluating usability, continuity, privacy and support.','[{"heading":"Start with people","paragraphs":["Consider the confidence, devices and working conditions of the people who will use the system. A technically complete tool can still fail if everyday tasks are difficult to understand."]},{"heading":"Ask about continuity","paragraphs":["Clarify data ownership, exports, backups, support, onboarding and what happens when responsibilities change."]},{"heading":"Evaluate with real work","paragraphs":["A useful demonstration should follow common church tasks with representative information and enough time for the people responsible to ask questions."]}]'::jsonb,'Church Govern editorial team',5,false,'2026-04-30T00:00:00Z'::timestamptz,'{"title":"Choosing technology that serves community","description":"A church-focused checklist for evaluating usability, continuity, privacy and support.","canonicalUrl":"/blogs/choosing-technology-that-serves-community"}'::jsonb)
) seeded(category_slug,slug,title,excerpt,content,author_name,read_time_minutes,featured,published_at,seo) join public.blog_categories category on category.slug=seeded.category_slug
on conflict (slug) do nothing;

insert into public.faqs(category,question,answer,sort_order,is_published) values
  ('Product','What is Church Govern?','Church Govern is a church administration and member-engagement platform intended to bring records, everyday workflows and communication into one secure digital environment.',1,true),
  ('Product','Is it suitable for every denomination?','The product is being designed as denomination-neutral. A church’s structure, terminology and enabled workflows would be confirmed during discovery and implementation.',2,true),
  ('Pricing','How much does Church Govern cost?','Pricing has not yet been published. It will depend on the implementation scope, enabled modules and service requirements. Request a consultation for a documented proposal.',3,true),
  ('Security','Who can access church information?','Access is intended to be role-based so people see only what their responsibilities require. Final permission roles and governance rules must be configured with each church.',4,true),
  ('Security','Is Church Govern DPDP and GDPR compliant?','The platform is designed to support privacy-conscious implementation, but compliance depends on configuration, contracts and the church’s own processes. Formal legal and compliance documentation will be provided before production onboarding.',5,true),
  ('Digitization','Can you help digitize old registers?','Church Govern is planning a digitization enquiry service for historical and current records. Record condition, volume, page size, location and handling requirements must be assessed before a proposal is confirmed.',6,true),
  ('Deployment','Where is the platform hosted?','The final hosting architecture and data-region options are awaiting approved product documentation. These details should be confirmed as part of a security and deployment review.',7,true),
  ('Support','What support is available?','The support model, service hours and response targets will be documented in the implementation proposal. This website does not yet make an unsupported service-level claim.',8,true),
  ('Implementation','How does implementation begin?','Implementation begins with discovery: church structure, records, roles, workflows, integrations, migration needs and success criteria. A phased plan can then be agreed before configuration starts.',9,true),
  ('Implementation','Can we begin with only a few modules?','A phased rollout is expected to be possible, subject to final product and commercial confirmation. The discovery process identifies useful starting workflows and dependencies.',10,true)
on conflict (question) do nothing;

